<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model { protected $fillable=['farmer_id','category_id','market_id','name','slug','description','price','unit','stock_quantity','image','is_available']; protected $casts=['price'=>'decimal:2','is_available'=>'boolean']; public function farmer(){return $this->belongsTo(User::class,'farmer_id');} public function category(){return $this->belongsTo(Category::class);} public function market(){return $this->belongsTo(Market::class);} public function reviews(){return $this->hasMany(Review::class);} }
